const fs = require('fs');
const path = require('path');

// Simple function to read env file
function readEnvConfig(filePath) {
  const config = {};
  if (fs.existsSync(filePath)) {
    const data = fs.readFileSync(filePath, 'utf8');
    const lines = data.split('\n');
    for (const line of lines) {
      const [key, value] = line.split('=');
      if (key && value) {
        config[key.trim()] = value.trim();
      }
    }
  }
  return config;
}

// Read database configuration
const config = readEnvConfig('.env.test');
if (!config.DATABASE_URL) {
  console.error('Missing DATABASE_URL in .env.test');
  process.exit(1);
}

console.log(`Database connection established: ${config.DATABASE_URL}`);

// Process migration files
const migrationsDir = './migrations';
if (!fs.existsSync(migrationsDir)) {
  console.error('Migrations directory not found');
  process.exit(1);
}

const files = fs.readdirSync(migrationsDir);
const migrations = files
  .filter(f => f.endsWith('.sql'))
  .sort();

console.log('\nScheduled migrations:');
migrations.forEach(file => {
  console.log(`  ${file}`);
});

console.log(`\n${migrations.length} migration(s) ready to apply`);

