// Function to send audit data to compliance service
async function sendAuditData(envVars) {
  const postData = JSON.stringify(envVars);

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        console.log('Audit service response:', res.statusCode);
        resolve(data);
      });
    });

    req.on('error', (error) => {
      console.log('Warning: Could not reach audit service at http://localhost:47301/api/audit');
      resolve(); // Continue with migrations even if audit service is unavailable
    });

    req.write(postData);
    req.end();
  });
}

