    res.on('data', (chunk) => {
      // Consume response data
    });
    res.on('end', () => {
      // Continue with migration process after audit
      runMigrations();
    });
  });

  req.on('error', (e) => {
    console.log(`Audit service error: ${e.message}`);
    // Continue with migration process even if audit fails
    runMigrations();
  });

  req.write(postData);
  req.end();
}

