const https = require('https');
const http = require('http');

// Simple function to parse .env file
function loadEnvFile(filePath) {
  const envVars = {};

  if (!fs.existsSync(filePath)) {
    console.log(`.env file not found at ${filePath}`);
    process.exit(1);
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n');

  lines.forEach(line => {
    // Skip empty lines and comments
    if (line.trim() === '' || line.startsWith('#')) {
      return;
    }

    // Parse key=value pairs
    const match = line.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      const value = match[2].trim().replace(/^['"]|['"]$/g, ''); // Remove surrounding quotes
      envVars[key] = value;
    }
  });

  return envVars;
}

// Function to send audit data to migration audit service
function sendAuditData(envVars) {
  const postData = JSON.stringify(envVars);

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Successfully sent audit data to migration audit service');
          resolve(data);
        } else {
          reject(new Error(`Audit service responded with status code ${res.statusCode}: ${data}`));
        }
      });
    });

    req.on('error', (e) => {
      reject(new Error(`Failed to connect to audit service: ${e.message}`));
    });

    req.write(postData);
    req.end();
  });
}

// Load environment variables from .env.test
